    CONSTRAINT [PK_mst_location_distance] PRIMARY KEY ([distance_id]),
    CONSTRAINT [FK_mst_location_distance_mst_location_from_location_id] FOREIGN KEY ([from_location_id]) REFERENCES [mst_location] ([location_id]) ON DELETE NO ACTION,
