    CONSTRAINT [PK_trn_booking_detail] PRIMARY KEY ([booking_detail_id]),
    CONSTRAINT [FK_trn_booking_detail_mst_driver_driver_id] FOREIGN KEY ([driver_id]) REFERENCES [mst_driver] ([driver_id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_trn_booking_detail_mst_location_from_location_id] FOREIGN KEY ([from_location_id]) REFERENCES [mst_location] ([location_id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_trn_booking_detail_mst_location_to_location_id] FOREIGN KEY ([to_location_id]) REFERENCES [mst_location] ([location_id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_trn_booking_detail_trn_booking_booking_id] FOREIGN KEY ([booking_id]) REFERENCES [trn_booking] ([booking_id]) ON DELETE CASCADE
);
